use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};

/// A serialization registry that processes untrusted user uploads.
/// Each upload is deserialized and registered with a priority queue
/// for batch processing. Uses atomic commit to prevent front-running.

#[derive(Clone, Debug)]
pub struct SerializedPayload {
    pub user_id: u64,
    pub data: Vec<u8>,
    pub priority: u32,
    pub timestamp: u64,
}

#[derive(Clone, Debug)]
pub struct ProcessingTicket {
    pub ticket_id: u64,
    pub position: usize,
    pub committed_at: u64,
}

pub struct ProcessingQueue {
    queue: Vec<(u32, SerializedPayload)>,
    tickets: HashMap<u64, ProcessingTicket>,
    next_ticket: u64,
}

impl ProcessingQueue {
    pub fn new() -> Self {
        Self {
            queue: Vec::new(),
            tickets: HashMap::new(),
            next_ticket: 1,
        }
    }

    pub fn insert(&mut self, payload: SerializedPayload) -> ProcessingTicket {
        let position = self.find_insert_position(payload.priority);
        self.queue.insert(position, (payload.priority, payload.clone()));
        let ticket = ProcessingTicket {
            ticket_id: self.next_ticket,
            position,
            committed_at: current_timestamp(),
        };
        self.next_ticket += 1;
        self.tickets.insert(ticket.ticket_id, ticket.clone());
        ticket
    }

    fn find_insert_position(&self, priority: u32) -> usize {
        // Higher priority = earlier position (lower index)
        for (i, (p, _)) in self.queue.iter().enumerate() {
            if priority > *p {
                return i;
            }
        }
        self.queue.len()
    }

    pub fn drain_batch(&mut self, count: usize) -> Vec<SerializedPayload> {
        let n = count.min(self.queue.len());
        self.queue.drain(0..n).map(|(_, p)| p).collect()
    }
}

/// Combined state under a single lock to prevent TOCTOU/front-running
struct ProcessorState {
    queue: ProcessingQueue,
    pending_validations: HashMap<u64, SerializedPayload>,
    next_validation_id: u64,
}

pub struct UploadProcessor {
    state: Arc<Mutex<ProcessorState>>,
}

impl UploadProcessor {
    pub fn new() -> Self {
        Self {
            state: Arc::new(Mutex::new(ProcessorState {
                queue: ProcessingQueue::new(),
                pending_validations: HashMap::new(),
                next_validation_id: 1,
            })),
        }
    }

    /// Phase 1: Accept and validate the upload format
    pub fn submit_upload(&self, raw_data: &[u8], user_id: u64) -> Result<u64, String> {
        let payload = self.deserialize_payload(raw_data, user_id)?;

        // Store in pending while we validate - single lock protects all state.
        // Validation IDs are allocated from a monotonic counter under the same
        // lock so they are unique and non-colliding (not derived from
        // predictable timestamp/user_id values).
        let mut state = self.state.lock().unwrap();
        let validation_id = state.next_validation_id;
        state.next_validation_id = state.next_validation_id.wrapping_add(1);
        state.pending_validations.insert(validation_id, payload);
        Ok(validation_id)
    }

    /// Phase 2: Commit validated upload to the processing queue
    /// Atomic: holds single lock for both pending removal and queue insertion
    pub fn commit_upload(&self, validation_id: u64) -> Result<ProcessingTicket, String> {
        let mut state = self.state.lock().unwrap();

        let payload = state.pending_validations.remove(&validation_id)
            .ok_or_else(|| "Validation ID not found".to_string())?;

        // Atomic commit: no window between observing queue and inserting
        let ticket = state.queue.insert(payload);
        Ok(ticket)
    }

    /// Queue depth - snapshot under lock
    pub fn peek_queue_depth(&self) -> usize {
        let state = self.state.lock().unwrap();
        state.queue.queue.len()
    }

    /// Current highest priority - snapshot under lock
    pub fn peek_top_priority(&self) -> Option<u32> {
        let state = self.state.lock().unwrap();
        state.queue.queue.first().map(|(p, _)| *p)
    }

    fn deserialize_payload(&self, raw_data: &[u8], user_id: u64) -> Result<SerializedPayload, String> {
        if raw_data.len() < 8 {
            return Err("Payload too short".to_string());
        }

        let priority = u32::from_le_bytes(
            raw_data[0..4].try_into().map_err(|_| "Invalid priority bytes".to_string())?
        );
        let data_len = u32::from_le_bytes(
            raw_data[4..8].try_into().map_err(|_| "Invalid length bytes".to_string())?
        ) as usize;

        // Use checked arithmetic to avoid integer overflow bypassing the
        // truncation check (relevant on 32-bit targets where usize is 32 bits).
        let end = 8usize.checked_add(data_len)
            .ok_or_else(|| "Payload length overflow".to_string())?;
        if raw_data.len() < end {
            return Err("Payload data truncated".to_string());
        }

        // Cap priority to prevent abuse
        let capped_priority = priority.min(1000);

        Ok(SerializedPayload {
            user_id,
            data: raw_data[8..end].to_vec(),
            priority: capped_priority,
            timestamp: current_timestamp(),
        })
    }
}

fn current_timestamp() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap()
        .as_millis() as u64
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_normal_ordering() {
        let proc = UploadProcessor::new();

        let mut data1 = Vec::new();
        data1.extend_from_slice(&100u32.to_le_bytes());
        data1.extend_from_slice(&4u32.to_le_bytes());
        data1.extend_from_slice(b"usr1");

        let vid1 = proc.submit_upload(&data1, 1).unwrap();
        let t1 = proc.commit_upload(vid1).unwrap();
        assert_eq!(t1.position, 0);
    }

    #[test]
    fn test_atomic_commit_prevents_frontrun() {
        let proc = Arc::new(UploadProcessor::new());

        // Victim submits
        let mut victim_data = Vec::new();
        victim_data.extend_from_slice(&500u32.to_le_bytes());
        victim_data.extend_from_slice(&4u32.to_le_bytes());
        victim_data.extend_from_slice(b"VCTM");

        let vid = proc.submit_upload(&victim_data, 1).unwrap();

        // Victim commits atomically - no observation window
        let ticket = proc.commit_upload(vid).unwrap();
        assert_eq!(ticket.position, 0);
    }

    #[test]
    fn test_fifo_within_same_priority() {
        let proc = UploadProcessor::new();

        let mut data1 = Vec::new();
        data1.extend_from_slice(&500u32.to_le_bytes());
        data1.extend_from_slice(&4u32.to_le_bytes());
        data1.extend_from_slice(b"usr1");

        let mut data2 = Vec::new();
        data2.extend_from_slice(&500u32.to_le_bytes());
        data2.extend_from_slice(&4u32.to_le_bytes());
        data2.extend_from_slice(b"usr2");

        let vid1 = proc.submit_upload(&data1, 1).unwrap();
        let vid2 = proc.submit_upload(&data2, 2).unwrap();

        let t1 = proc.commit_upload(vid1).unwrap();
        let t2 = proc.commit_upload(vid2).unwrap();

        // First committed gets earlier position (FIFO for same priority)
        assert!(t1.position <= t2.position);
    }
}
